// Generating function: testRunesAndStrings
void testRunesAndStrings() {
    std::string s = "Hello, 世界";
    std::cout << "String: " << s << std::endl;
    std::cout << "String length: " << s.length() << std::endl;
    
    // Iterate over characters (approximating Go's range over runes)
    for (size_t i = 0; i < s.length(); ) {
        // This is a simplified approach to handle UTF-8 characters
        unsigned char ch = s[i];
        int char_len = 1;
        
        // Determine UTF-8 character length
        if ((ch & 0x80) == 0) {
            char_len = 1;
        } else if ((ch & 0xE0) == 0xC0) {
            char_len = 2;
        } else if ((ch & 0xF0) == 0xE0) {
            char_len = 3;
        } else if ((ch & 0xF8) == 0xF0) {
            char_len = 4;
        }
        
        std::string rune = s.substr(i, char_len);
        std::cout << "Character " << i << ": " << rune << std::endl;
        i += char_len;
    }
}

